"""Tiny GOAP planner using A* over state space.

World state is a frozenset of true boolean facts (e.g. {"has_wood"}).
Actions have preconditions (facts required), effects (facts added), cost.
"""
import heapq


class Action:
    def __init__(self, name, preconditions=(), effects=(), cost=1):
        self.name = name
        self.preconditions = frozenset(preconditions)
        self.effects = frozenset(effects)
        self.cost = cost

    def applicable(self, state):
        return self.preconditions <= state

    def apply(self, state):
        return state | self.effects

    def __repr__(self):
        return f"Action({self.name!r})"


def _reconstruct(came_from, node):
    plan = []
    while node in came_from:
        prev, action = came_from[node]
        plan.append(action)
        node = prev
    plan.reverse()
    return plan


def make_plan(start_state, goal_state, actions):
    """A* search from start_state to goal_state.

    Returns a list of Actions achieving the goal, or None if impossible.
    Heuristic: number of unmet goal facts.
    """
    start = frozenset(start_state)
    goal = frozenset(goal_state)

    def h(state):
        return len(goal - state)

    open_heap = [(h(start), 0, start)]
    came_from = {}
    g_score = {start: 0}
    closed = set()

    while open_heap:
        _, g, current = heapq.heappop(open_heap)
        if current in closed:
            continue
        closed.add(current)

        if goal <= current:
            return _reconstruct(came_from, current)

        for action in actions:
            if not action.applicable(current):
                continue
            neighbor = action.apply(current)
            tentative_g = g + action.cost
            if tentative_g < g_score.get(neighbor, float("inf")):
                g_score[neighbor] = tentative_g
                came_from[neighbor] = (current, action)
                heapq.heappush(
                    open_heap,
                    (tentative_g + h(neighbor), tentative_g, neighbor),
                )

    return None

